INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Guild 3', 'The Guild 3 is a fascinating trade and life simulation that takes place during the late Middle Ages. Step into the shoes of a citiizen, acquire businesses and mansions, produce goods and trade them, start intrigues in politics and society, love, hate, bribe, fight and live through good and bad times!' FROM games WHERE igdb_id = 13165 ON CONFLICT (game_id, language_code) DO NOTHING;
