INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 18', 'EA SPORTS NHL 18 delivers the speed, creativity and action of today''s young NHL superstars with new Creative Attack controls and an all-new Defensive Skill Stick. Play the fast-paced, arcade-inspired 3-on-3 NHL THREES mode, or create your own custom 32nd NHL team with the new Expansion Draft. Do it all with the most co-op and competitive multiplayer options ever in an EA SPORTS NHL game.' FROM games WHERE igdb_id = 36847 ON CONFLICT (game_id, language_code) DO NOTHING;
