INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Champions of Odin', 'Champions of Odin is a first-person, action role-playing game that combines the fast pace and intensity of a first-person shooter with RPG elements. The story and theme of the game draw from Norse Mythology. Play as a magical frost giant who is forced to make a deal with Odin, the god of all gods!' FROM games WHERE igdb_id = 55629 ON CONFLICT (game_id, language_code) DO NOTHING;
