INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetsoidea Eternal', 'Follow Evelyn and company in this delightful RPG to determine the whereabouts of the other heroes of the realm of Tetsoidea. Engage in difficult encounters, easy encounters, and laughable encounters. Travel through a variety of settings. Talk to people, horses, and dogs. Do whatever you feel like, so long as you vanquish the evil that has spread throughout the land.' FROM games WHERE igdb_id = 52074 ON CONFLICT (game_id, language_code) DO NOTHING;
