INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IKEA VR Pancake Kitchen', 'Welcome to the IKEA Virtual Reality kitchen experience, where you can make some virtual pancakes. Our IKEA kitchen specialist will guide you through some of the key aspects of a well-planned kitchen. And look out for the instructions that will help you to prepare those perfect pancakes.' FROM games WHERE igdb_id = 43982 ON CONFLICT (game_id, language_code) DO NOTHING;
