INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Children of the Galaxy', 'Children of the Galaxy is a grand scale 4x turn-based strategy game with a turn-based combat and tactical elements. You can explore the galaxy, colonize planets and build huge armies of starships to fight in epic space battles.' FROM games WHERE igdb_id = 30304 ON CONFLICT (game_id, language_code) DO NOTHING;
