INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Montana Chronicles: Montana''s Croatoa', 'Building on classical maze crawlers, Montana''s Croatoa is an attempt to break away from grid based movement in dungeon crawling puzzle based games. In real time the player must escape from the maze of enemies with limited sight. To make things more difficult, in each level the player must activate a switch which will power the elevator to the next floor. A variety of enemies makes each level it''s own challenge.' FROM games WHERE igdb_id = 46472 ON CONFLICT (game_id, language_code) DO NOTHING;
