INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Theft Auto V: Premium Edition & Great White Shark Card Bundle', 'The Grand Theft Auto V: Premium Edition & Great White Shark Card Bundle includes the complete Grand Theft Auto V story experience, free access to the ever-evolving Grand Theft Auto Online and all existing gameplay upgrades and content, including The Cayo Perico Heist, The Diamond Casino & Resort, The Diamond Casino Heist, Gunrunning and much more. Players also get the Criminal Enterprise Starter Pack, the fastest way to jumpstart their criminal empire in Grand Theft Auto Online, plus a Great White Shark Cash Card worth $1,250,000 in-game GTA dollars to spend in GTA Online.' FROM games WHERE igdb_id = 143295 ON CONFLICT (game_id, language_code) DO NOTHING;
