INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuza 0: Digital Deluxe Edition', 'Yakuza 0 is an action-adventure game developed by Ryu Ga Gotoku Studio and published by Sega. Serving as a prequel to the Yakuza series, it is set in 1988 Japan during the country''s economic bubble era. The game follows two protagonists: Kazuma Kiryu in Tokyo''s Kamurocho district and Goro Majima in Osaka''s Sotenbori district. Players alternate between their stories as they navigate the criminal underworld, engaging in street fights, managing businesses, and participating in various side activities.
