INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trash Truck Simulator', 'Driving a garbage truck in city environment is the ultimate test of driving skill. Take a seat and start your job in a fully modeled and animated trucks that are based on real truck models. Load up the truck and deliver the trash to your garbage processing plant, where it will be burned. Burning the trash generates you money, which you can use to upgrade furnaces in the plant, or buy different trucks. There are many trucks to choose from.' FROM games WHERE igdb_id = 382650 ON CONFLICT (game_id, language_code) DO NOTHING;
