INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Potion Destroyer', 'Escape from the witch’s mansion! This is a strategic escape game. Use “Mana Reinforcement” and “Magic Potions” to power Claudia up and make your way through the 30 stages of the witch’s mansion to escape to freedom. There are five possible endings to the game, each of which requires specific conditions to be filled. Will you be able to make it out of the mansion safely and achieve the best ending possible?!' FROM games WHERE igdb_id = 55227 ON CONFLICT (game_id, language_code) DO NOTHING;
