INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seven Photos', 'Seven Photos is a murder mystery game where you have 7 photos to figure out exactly how and why you woke up, without memories, outside a locked room containing two presumably dead people. You try to figure out who the murderer is before you go insane. Could it have been you? Who''s lying? You have seven photos to figure that out.' FROM games WHERE igdb_id = 122945 ON CONFLICT (game_id, language_code) DO NOTHING;
