INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guns of Icarus Alliance', 'Guns of Icarus Alliance is the complete PvE experience while maintaining all the PvP contents, including achievements, progression, cosmetics, and data from Guns of Icarus Online. From a single pilot to as many as 16 players can unite in their battle for the wasteland, completing objectives in all new PvE/Co-op game modes like capturing cargo or destroying drilling platforms. You just need to grab your friends and go. Choose a faction and unlock their special costumes, weapons, and airships as each victory brings your faction one step closer to their ultimate goal of reshaping the world.' FROM games WHERE igdb_id = 21989 ON CONFLICT (game_id, language_code) DO NOTHING;
