INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heat Signature', 'Fly your tiny defenceless pod up to larger ships, dock with their airlock, and sneak inside. Once you''re in, you creep through their corridors, ambushing guards, hiding bodies, stealing new weapons, blowing them up from the inside, or hijacking their turrets and even the whole ship.' FROM games WHERE igdb_id = 10160 ON CONFLICT (game_id, language_code) DO NOTHING;
