INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Styx: Shards of Darkness', 'Embark upon a stealthy adventure with new enemies, new environments, and a plethora of new mechanics aimed at refining the abilities and movement of Styx; grappling around corners, climbing ropes, and using his trusty knife as a zip-wire. Shards of Darkness aims to offer unparalleled freedom of movement, along with refined stealth and assassination mechanics, expanding and improving on the strengths of Styx: Master of Shadows' FROM games WHERE igdb_id = 13554 ON CONFLICT (game_id, language_code) DO NOTHING;
