INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Art of Knuckle Sandwich', 'You''ve trained since you were barely able to walk, creating secret techniques and forms to develop a new martial art known as Knuckle Sandwich. Now with your art perfected you approach the masters of martial arts in your land and demand recognition for your discipline. Greeted with mockery and taunts you are forced to travel the land and show the people the true power of the Knuckle Sandwich.' FROM games WHERE igdb_id = 55291 ON CONFLICT (game_id, language_code) DO NOTHING;
