INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totemori', 'Totemori is play-for-free arena game enjoyable both in multiplayer and single player modes. Your task is to build the tallest possible towers from the building blocks airdropping onto the playing field, and concurrently break your foes'' attempts of doing the same. Toss them off the map, or if things really go south blow up everything and level the playing field. Literally.' FROM games WHERE igdb_id = 27207 ON CONFLICT (game_id, language_code) DO NOTHING;
