INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where''s the Fck*ng Light - VR', 'After a relaxing weekend at a remote Hotel in New York, your last night is nearing. Because of the fact that your last night has ended, you should go home, but everything seems to ocurr so early. After noticing strange sounds in the middle of the night, you will decide to look what is happening there.' FROM games WHERE igdb_id = 30948 ON CONFLICT (game_id, language_code) DO NOTHING;
