INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Everspace: Ultimate Edition', 'Everspace combines fast-paced combat with roguelike elements, great visuals and a captivating story. It takes you on a challenging journey through an ever-changing, beautifully crafted universe full of surprises. Shoot, craft and loot your way to victory while the odds are stacked against you.' FROM games WHERE igdb_id = 361101 ON CONFLICT (game_id, language_code) DO NOTHING;
