INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animality', 'Animality is a skill based animal runner game, the goal of the game is to avoid dragons and demons all whilst trying to grab life gems, either do this singleplayer or with your friend in local multiplayer co-op, you can collect 9 fabulous pixel art animals which are purchased using your running cash!' FROM games WHERE igdb_id = 29914 ON CONFLICT (game_id, language_code) DO NOTHING;
