INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Will: A Wonderful World', 'Become a god and help change the fate of people, even the world! In Will: A Wonderful World, you will receive letters written by characters living in urban cities. By rearranging the order and combinations of sentences in these letters, you are going to alter the destiny of whomever that wrote them.' FROM games WHERE igdb_id = 34657 ON CONFLICT (game_id, language_code) DO NOTHING;
