INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Expression Amrilato', 'In "The Expression Amrilato", the main character is lost in an alternate world where Juliamo (which in the real world is Esperanto, an existing constructed language.) is the official spoken language. Therefore, while enjoying a story between cute girls, you can also learn the Esperanto language! The text in this game has been officially supervised by the National Esperanto Association in Japan.' FROM games WHERE igdb_id = 119580 ON CONFLICT (game_id, language_code) DO NOTHING;
