INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lazaretto', 'Lazaretto is a first-person survival horror video game set in the current day. You play the descendant of a man who once worked at an old and inactive facility, rumored to be located on a haunted quarantine island - a Lazaretto. Armed with only with a flashlight and nagging curiosity, your goal is to explore the environment, uncovering mysteries surrounding an artifact which has recently fallen into your possession.' FROM games WHERE igdb_id = 36454 ON CONFLICT (game_id, language_code) DO NOTHING;
