INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Chef Brigade Deluxe', 'Welcome to Victusia, where the members of the elite Battle Chef Brigade are revered for their ability to skillfully take down monsters and transform their kills into delicious cuisine! But getting in isn''t easy chefs from across Victusia must vie for their spot in a high stakes competition. Follow two contestants, Mina and Thrash, as their journeys through the tournament unfold. In order to become a Brigadier you''ll need to hunt monsters with combo-based attacks and prepare your freshly-caught ingredients in puzzle-based cooking challenges to serve up winning dishes to the judges – all while the round clock ticks down.' FROM games WHERE igdb_id = 111825 ON CONFLICT (game_id, language_code) DO NOTHING;
