INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dealer''s Life', 'Dealer''s Life is a tycoon game where you manage your pawn shop. Haggle with infinite randomly generated customers to buy and sell whatever items you can manage to score and offer! Have fun for hours and use all your negotiation, psychology, and management skills to create your pawn empire! Thanks to procedural generation, special characters, and random events, you’ll never know what’s coming next!' FROM games WHERE igdb_id = 114063 ON CONFLICT (game_id, language_code) DO NOTHING;
