INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glasswinged Ascension', 'Glasswinged Ascension is built around cyberpunk theme permeated with avoidance, caution, and story telling. It is truly hardcore, and consists of missions which can be completed in different ways. There is no straight path to the goal, while means to achieve it do not have to be lethal.' FROM games WHERE igdb_id = 46484 ON CONFLICT (game_id, language_code) DO NOTHING;
