INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The LEGO Ninjago Movie Video Game', 'Find your inner ninja with the all-new LEGO Ninjago Movie Video Game! Play as your favorite ninjas, Lloyd, Jay, Kai, Cole, Zane, Nya and Master Wu to defend Ninjago City from the evil Lord Garmadon and his Shark Army. Master the art of Ninja-gility by wall-running, high-jumping and battling the foes of Ninjago to rank up and upgrade the ninja’s combat skills. Only in the LEGO Ninjago Movie Video Game will you experience the film across 8 action packed locations each with its own unique Challenge Dojo. And with the Battle Maps, play against friends and family in competitions for up to four players!' FROM games WHERE igdb_id = 52190 ON CONFLICT (game_id, language_code) DO NOTHING;
