INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Everything', 'Everything is an interactive experience where everything you see is a thing you can be, from animals to planets to galaxies and beyond. Travel between outer and inner space, and explore a vast, interconnected universe of things without enforced goals, scores, or tasks to complete. Everything is a procedural, AI-driven simulation of the systems of nature, seen from the points of view of everything in the Universe. Narrated by the late British philosopher Alan Watts.' FROM games WHERE igdb_id = 27910 ON CONFLICT (game_id, language_code) DO NOTHING;
