INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forestry', 'So it begins. Your dreams of being lost in the woods have come to life! Chop down trees, sit by the lake, find the secrets, build a fortress, impress your friends, and master the skills required for making your way in the world. Welcome to Forestry.' FROM games WHERE igdb_id = 29950 ON CONFLICT (game_id, language_code) DO NOTHING;
