INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights With 39', 'You have been called out, by a teal animatronic bunny with glasses, his name is 39. He has a strange personality, something you wouldn''t see in your average animatronic, he''s foul, he''s roudy, he''s stupid, and he''s coming for you! Survive his random movements, and his little pal that will surely end you if you are not quick enough, boop his nose to keep him away!' FROM games WHERE igdb_id = 263638 ON CONFLICT (game_id, language_code) DO NOTHING;
