INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Einlanzer', 'Einlanzer is a full-scale, epic fantasy role-playing game. The story of Einlanzer was written by a professional fantasy novelist, and has 28 original music tracks. Einlanzer has a highly strategic battle system, massive scope, and difficult moral decisions that permanently affect the storyline.' FROM games WHERE igdb_id = 30575 ON CONFLICT (game_id, language_code) DO NOTHING;
