INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Party: The Top 100', 'Mario Party: The Top 100 is a party compilation that brings together 100 of the series’ most memorable mini‑games from classic entries, optimized for quick competitive or casual sessions. Players compete in bite‑sized challenges that capture the series’ variety (timing tests, reflex puzzles, skill contests), either locally or in short online matches, preserving the pick‑up‑and‑play chaos and charm of Mario Party across multiple eras.' FROM games WHERE igdb_id = 66812 ON CONFLICT (game_id, language_code) DO NOTHING;
