INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Trapland 2: Curiosity', 'The adventures of Bloody Trapland is back! Bloody Trapland is a fast-paced multiplayer platformer where the levels are filled with dozens of dangerous traps and tricky jumps that stand in your way! Play co-op with your friends or take on the challenges on your own. With support for up to 4 players at once, local and/or online. This is a challenging, yet simple game that anyone can enjoy, whether you''re a casual or a hardcore gamer.' FROM games WHERE igdb_id = 28003 ON CONFLICT (game_id, language_code) DO NOTHING;
