INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meleng', 'Meleng is a logic puzzle game played on a grid of square cells. This grid also contains circles with dots which indicates how many lines must crosses at that point. You must complete the grid by filling in every cell with lines and linking them with or away from each other.' FROM games WHERE igdb_id = 74640 ON CONFLICT (game_id, language_code) DO NOTHING;
