INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giant Cop: Justice Above All', 'You ARE Giant Cop. It’s your first day on the job and you need to hit the ground running in order to keep the citizens of Micro City safe. Use your size to your advantage as you tower high above the city’s streets enforcing the law. In Micro City’s open world, how you maintain order is up to you! Will you manage the city with an iron first, or a soft hand?' FROM games WHERE igdb_id = 18429 ON CONFLICT (game_id, language_code) DO NOTHING;
