INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Sweet Angel', 'A clicker game where the player earns Angel Points (AP) by either tapping the screen or through the generation of the protagonist''s girlfriend''s multiple transformations. Angel Points can also be earned when the game is closed through generation. Completing achievements unlocks bonus story events, and upgrades are purchaseable to make progression faster.' FROM games WHERE igdb_id = 340342 ON CONFLICT (game_id, language_code) DO NOTHING;
