INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beat Fever: Music Planet', 'Tap to the beat of the biggest songs from Nicki Minaj, Sia, Daddy Yankee, Marshmello, Lady Gaga, Beethoven and hundreds more! Beat Fever is the ultimate music game featuring top hits from pop, rock, EDM, classical, latin, hip-hop and more! Play the top hits in the world like Despacito, Super Bass, Uptown Funk, Poker Face, Happy and Beethoven’s 5th! Discover new music added EVERY MONTH from tomorrow’s biggest singers, bands, DJs, composers, and rappers.' FROM games WHERE igdb_id = 105466 ON CONFLICT (game_id, language_code) DO NOTHING;
