INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grimoire: Heralds of the Winged Exemplar', 'Cleveland Mark Blakemore''s Magnum Opus! The ultimate classic style turn-based roleplaying game in the tradition of Wizardry, Might&Magic, Lands Of Lore and Eye of the Beholder! A game that took over 20 years to produce! As much as 600 hours of play with hand-painted graphics and old skool goodness!' FROM games WHERE igdb_id = 43487 ON CONFLICT (game_id, language_code) DO NOTHING;
