INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Austen Translation', 'Austen Translation is a tongue-in-cheek strategy game which borrows heavily from the visual novel tradition. It can be played solo against bots or as a multi-player match with up to five players. Randomly combined plot elements, settings, endings and rivals make each playthrough feel fresh.' FROM games WHERE igdb_id = 68768 ON CONFLICT (game_id, language_code) DO NOTHING;
