INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Shroom Project', 'The zombie apocalypse is nigh! The world is in utter chaos, and death is commonplace. A malicious group is responsible for all of this destruction, and is busy at work on a dark scheme known as The Shroom Project. Play as one of two characters, join a rag tag team known as The Resistance, and fight back against a mysterious, yet, familiar face!' FROM games WHERE igdb_id = 320236 ON CONFLICT (game_id, language_code) DO NOTHING;
