INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seven Boys', 'You play the role of the heroine who has traveled to the fairy tale world to help seven cute little boys run a dying inn. All you need to do is to choose one to raise every day for ten days. As time passes, you will gradually realize that this world is not as beautiful as imagined, and there are unexpected truths hidden behind the peace and happiness. As an "outsider", you must discover the truth!' FROM games WHERE igdb_id = 94067 ON CONFLICT (game_id, language_code) DO NOTHING;
