INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aokana-four-rhythms-across-the-blue-extra1', 124028, '2017-06-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jsv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar113h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aokana: Four Rhythms Across the Blue Extra1', 'Mashiro thought that she has finally reached the happy end. However, she was barely passing her classes. She lost completely in a sweets battle to Rika and Arika. On top of that, Misaki and Asuka declared that they are Masaya’s lovers!? At this rate, her dear senpai would be taken from her, she’ll have to repeat a year, and Mashiro Udon would go out of business!? Mashiro’s mother, Botan, suddenly suggested that she and Masaya go on an overnight date. She declared that she’ll make a tasty bento for him and dress up nicely. With the help of the others, she trained really hard to up her feminine qualities before the date. Will they reach the true happy end!?' FROM games WHERE igdb_id = 124028 ON CONFLICT (game_id, language_code) DO NOTHING;
