INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s not stay friends', 'Friendship is a wonderful thing… unless you are friends with a girl who has no idea you have feelings for her! Inske, a student of magical arts, is troubled by the upcoming outdoors exam, and can''t even imagine that someone might want to use the test as an opportunity to get close to her. Meanwhile, the number of applicants for her heart only increases… And while she’s busy figuring out her feelings, she still needs to survive and get a good grade!' FROM games WHERE igdb_id = 76484 ON CONFLICT (game_id, language_code) DO NOTHING;
