INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Botlike: A Robot''s Rampage', 'Botlike - loot and shoot your way through hordes of robots or die trying. Play as S.I.R. - a grumpy old warbot on his path to revenge. Use your ever-growing arsenal of weapons, upgrades and powerful items to defeat an evil and totalitarian robot league. Grab your top hat and let the rampage begin.' FROM games WHERE igdb_id = 53310 ON CONFLICT (game_id, language_code) DO NOTHING;
