INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reflex Arena', '"Reflex Arena is a return to roots, pure, fast, first person shooter. You will be pushed to your limits facing other contestants in a range of rich and diverse arena-base environments. Delivering a truly rewarding experience based purely on your skill and success. Train to unlock your genetic potential and bring it online for the ultimate proving ground and make your mark. There are no limitations in Reflex Arena, the true evolution of the classic arena shooter genre."' FROM games WHERE igdb_id = 9075 ON CONFLICT (game_id, language_code) DO NOTHING;
