INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Succubi Trap', 'Can you face the curse of the succubus? A psychological hack-n-slash drain-to-trail maze game, The Succubi Trap is a mind numbing unraveling of the human psyche where the effect of the echoes you hear in this torturous maze shall creep into your reality and persist for days.' FROM games WHERE igdb_id = 74354 ON CONFLICT (game_id, language_code) DO NOTHING;
