INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Lucky''s Tale', 'Super Lucky’s Tale is a delightful, playground platformer for all ages that follows Lucky, the ever-optimistic and lovable hero, on his quest to find his inner strength and help his beloved sister rescue the Book of Ages from the nefarious Jinx. Head back to the era of classic platformers with challenges players of all skill levels and all ages can enjoy.' FROM games WHERE igdb_id = 37024 ON CONFLICT (game_id, language_code) DO NOTHING;
