INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leylines', 'As a powerful wizard, you start by ruling a small nation as you plot to take over the world! Rule over seven diverse races, from shapeshifting Theria, to spider-riding Dwarves, to the decadent Regency. Explore a vast fantasy world, expand by building more cities, battle the armies of rival wizards, and cast earth-shattering enchantments to ensure your victory.  Leylines is a 4X game, a turn-based strategy game of exploration and conquest. The game features 150 different units and 80 different spells, customizable heroes and a map editor.' FROM games WHERE igdb_id = 29640 ON CONFLICT (game_id, language_code) DO NOTHING;
