INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Great Ace Attorney 2: Resolve', 'The Great Ace Attorney 2: Resolve is the eleventh installment of the Ace Attorney series of text adventure video games. New gameplay mechanics introduced to the series include Dance of Deduction, in which Ryunosuke must deduce mistakes and oversights in Herlock''s overboard logic and uncover new facts, and Summation Examination, in which players must point out discrepancies among jurors'' arguments to make their defendant''s case and ultimately secure a "Not Guilty" verdict.' FROM games WHERE igdb_id = 146081 ON CONFLICT (game_id, language_code) DO NOTHING;
