INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby''s Blowout Blast', 'Have a blast inhaling foes and blowing them away in 3D environments across 25+ stages. Inhale enough enemies and you can launch one huge Blaster Bullet capable of wiping out a troop of Waddle Dees. Now''s your chance to battle iconic bosses like Kracko Jr. and King Dedede in 3D!
