INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1-2-Switch', '1-2-Switch is a party game for everyone! Throw an impromptu party anywhere with anyone thanks to a new play style in which players look at each other—not the screen! Bring the action and fun into the real world as you face off in wild-west duels, cow-milking competitions, and more. While the action unfolds off-screen, the audience watches the players themselves instead of the screen.' FROM games WHERE igdb_id = 26762 ON CONFLICT (game_id, language_code) DO NOTHING;
