INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Dark Witch Episode 3: Wisdom and Lunacy', 'The Legend of Dark Witch 3 focuses on refining the Dark Witch series'' gameplay mechanics, removing many features present in The Legend of Dark Witch and The Legend of Dark Witch 2 while modifying others to create a more streamlined game. Dark Witch 3 does not feature Technical Skills or player-available Revenge Magics. Additionally, the Enhancement Gauge has been simplified to Speed, Wing, and Width, with Width functioning as a combination of the Liner and Power slots in previous games.' FROM games WHERE igdb_id = 79800 ON CONFLICT (game_id, language_code) DO NOTHING;
