INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flame in the Flood: Complete Edition', 'The Flame in the Flood: Complete Edition is a wilderness survival game in which a girl and her dog travel on foot and by raft down a procedurally-generated river. Scrounge for resources, craft tools, remedy afflictions, evade the vicious wildlife and, most importantly, stay healthy in a dangerous wilderness. This Complete Edition includes various gameplay enhancements and a Director’s Commentary mode. The Flame in the Flood also features an original soundtrack by acclaimed Alt-Country rocker Chuck Ragan featuring The Camaraderie, The Fearless Kin and other special guests.' FROM games WHERE igdb_id = 26181 ON CONFLICT (game_id, language_code) DO NOTHING;
