INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-lost-heir-3-demon-war', 27875, '2017-03-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ple.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cd29luvisjqjneraj3p4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lost Heir 3: Demon War', 'The Lost Heir 3: Demon War is a 250,000-word interactive fantasy novel where your choices control the story. The game is entirely text-based without graphics or sound effects and fueled by the vast, unstoppable power of your imagination. Face betrayal, seek romance, battle enemies in war, and navigate the intrigues of court. The fate of the kingdom of Daria is in your hands.' FROM games WHERE igdb_id = 27875 ON CONFLICT (game_id, language_code) DO NOTHING;
