INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sine Mora EX', 'Sine Mora EX is a side-scrolling shoot''em up that provides a unique challenge, where time is the ultimate factor. Mixing classic shooter sensibilities with contemporary presentation, Sine Mora is a gorgeous shoot''em up offering both a Story Mode that weaves an over-the-top tale and an Arcade Mode that provides deep, satisfying gameplay to challenge fans of the genre. The story mode can be also played in local co-op mode.' FROM games WHERE igdb_id = 27666 ON CONFLICT (game_id, language_code) DO NOTHING;
