INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Portal Knights', 'Leave the familiar world behind and step into the fantastic unknown with Portal Knights! Play with your friends in this action-packed crafting adventure across dozens of sandbox islands connected by ancient portals. No one can remember how long it’s been since the peaceful world was torn apart by The Fracture, plummeting it into darkness. Is there any soul brave enough to reunite the shattered realm? Craft your adventure. Forge your hero. Become the ultimate Portal Knight!' FROM games WHERE igdb_id = 20392 ON CONFLICT (game_id, language_code) DO NOTHING;
