INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventurer and His Backpack', 'This is a turn-based adventurous relaxing game with simple controls. You play as an adventurer, who brings a backpack with a limited number of slots. While adventuring, you will meet different kinds of monsters, defeat them, gain equipment with different functions and strengthen yourself to face stronger monsters.' FROM games WHERE igdb_id = 36823 ON CONFLICT (game_id, language_code) DO NOTHING;
