INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('empyre-lords-of-the-sea-gates', 47518, '2017-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24rc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkdd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empyre: Lords of the Sea Gates', '"Featuring a top-down isometric presentation, Empyre: Lords of the Sea Gates will rekindle old-school PC RPG fans with feelings of some of the classic story driven RPGs of the 90s. While the combat should feel familiar to veteran players, there’s a new twist in that the game uses a hybrid Real Time/Turn-based System. Players can enter a “Planning Mode” where they choose actions for each character in their party while combat is paused, and when entering into the “Action Mode” all characters will perform simultaneously, giving players complete control over their party while presenting a streamlined combat system that eliminates waiting for each character to act in sequence."' FROM games WHERE igdb_id = 47518 ON CONFLICT (game_id, language_code) DO NOTHING;
