INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dick Wilde', 'Those pesky swamp critters are at it again! Scarin’ off all the good folk who just want to go huntin’ and fishin’ on their lakes and lagoons! We’re talking piranhas, eels, ‘gators - you name it! There’s even been talk of a giant mutated Turtle on the loose! Good thing our fav’rite gun-slingin’, grenade-launchin’, cross-bow firin’ exterminator, Dick Wilde, is on standby to open up a can of whoop ass!' FROM games WHERE igdb_id = 29669 ON CONFLICT (game_id, language_code) DO NOTHING;
