INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yooka-Laylee', 'Explore huge, beautiful worlds, meet (and beat) an unforgettable cast of characters and horde a vault-load of shiny collectibles as buddy-duo Yooka (the green one) and Laylee (the wisecracking bat with the big nose) embark on an epic adventure to thwart corporate creep Capital B and his devious scheme to absorb all the world’s books… and convert them into pure profit!' FROM games WHERE igdb_id = 10031 ON CONFLICT (game_id, language_code) DO NOTHING;
