INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City of God I: Prison Empire', 'City of God I: Prison Empire is a prison themed RPG simulation game. Build your prison freely and make prisoners work for you with maximum efficiency by providing all kinds of prison facilities. Build different kinds of workshops to keep your prisoners working hard and earning money from the market. Find the specially skilled prisoners from the government and police database, and make those people work in your prison. Work as the warden to unlock different projects. Time your selling at the right time at the market. Make more money to expand your prison empire and use money to influence politicians and gangs in the city.' FROM games WHERE igdb_id = 32719 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 32719 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
