INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Coma: Recut', 'In this creepy Korean survival-horror you take the role of Youngho, a hapless student who finds himself trapped in the nightmarish halls of his high school. After drifting asleep during his final exam, he awakes in the school at night. The only problem is he''s not alone. Relentlessly pursued by a psychotic killer, he must now muster the courage to solve the mystery of why he is here and how to escape.' FROM games WHERE igdb_id = 51385 ON CONFLICT (game_id, language_code) DO NOTHING;
