INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Achievement Hunter: Urban 2', 'Dive into the heart-pounding action of Achievement Hunter: Urban 2, a thrilling 2D action shooter where you''re the last line of defense against an alien invasion! Step into the shoes of a fearless protagonist armed to the teeth and ready to take on hordes of extraterrestrial enemies threatening to obliterate your city. This isn''t a cooperative game; you''re flying solo.' FROM games WHERE igdb_id = 368943 ON CONFLICT (game_id, language_code) DO NOTHING;
