INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Horde', 'The horde is here to eat your brain and murder every single one of your scientists. Gather your forces, this is the last stand before we lose the facility! Place guards, close doors, and position traps. Survive as long as you can! Endless Horde is a Tower Defense game where the enemies spawn in different areas every time you play, don’t get too comfortable with a strategy or they will overrun you in no time! Each wave is a different experience.' FROM games WHERE igdb_id = 105890 ON CONFLICT (game_id, language_code) DO NOTHING;
