INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freedom Locomotion VR', 'Walk, jog, run, climb and crawl across a range of locations and terrains in the Freedom Locomotion VR demo. This game showcases the revolutionary Freedom Locomotion System that provides you with a wide range of options, which will allow you to find the most immersive fit regardless of how motion sickness sensitive you might be.' FROM games WHERE igdb_id = 29651 ON CONFLICT (game_id, language_code) DO NOTHING;
