INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OrbusVR', 'OrbusVR is the first fully-realized MMORPG designed from the ground up for room-scale VR. It features a huge open world with thousands of players, dozens of hours of quests following an intriguing story, interesting lore and characters, five-player group dungeons, world bosses, and more!' FROM games WHERE igdb_id = 76324 ON CONFLICT (game_id, language_code) DO NOTHING;
