INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Tales: Heart of the Forest', 'In this point and click adventure, there is a secret world hidden at the bottom of the forest: the magical kingdom of Brie where tiny humans live in harmony with animals. When little Max is called home to help his estranged mother, he never imagined it would be the biggest journey he would have to make.' FROM games WHERE igdb_id = 36951 ON CONFLICT (game_id, language_code) DO NOTHING;
