INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solitaire - Cat Pirate Portrait', 'Solitaire - Cat Pirate Portrait - Experience the crisp, clear, and easy to read cards, simple and quick animations, and nice sounds, you can play with portrait views. You can move cards with a single tap or drag them to their destination. You can either play the easy Draw 1 games where most games are winnable or if you feel up to the challenge, try your luck with Draw 3 and Vegas play modes. You can undo your last move.' FROM games WHERE igdb_id = 44268 ON CONFLICT (game_id, language_code) DO NOTHING;
