INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy of Pen and Paper', 'Galaxy of Pen & Paper is a turn-based meta RPG about a group of players rolling dice in the year 1999! Create your own game master and RPG party, as they roleplay, explore distant planets in their imagination, fight weird aliens and save the galaxy in the era of dial-up internet and floppy disks!' FROM games WHERE igdb_id = 44112 ON CONFLICT (game_id, language_code) DO NOTHING;
