INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arrow Heads', '"Arrow Heads is a fast paced multiplayer archery game, played from an isometric perspective. The game pits you against your avian counterparts in a heated deathmatch scenario. Should you find yourself against superior birds we have included five power ups that should help give your opponents the kick-in-the-pants they deserve. Join your friends on this zany 2-4 player adventure, where the chaotic moments wait around the corner. Whether you are slinging arrows or bear traps, the game will leave you wanting to come back for more!"' FROM games WHERE igdb_id = 22392 ON CONFLICT (game_id, language_code) DO NOTHING;
