INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solar Settlers', 'Solar Settlers is a card-driven space exploration strategy game set in the far future. Our sun is on the verge of collapse and so mankind has taken to the stars aboard colony ships to seek out a new home. You are the caretaker of one such ship, and must carefully manage the planets you find, technology cards you posses and fellow colonists as they gradually awaken from a long cryo-sleep in order to scratch out a new cradle for humanity.' FROM games WHERE igdb_id = 44139 ON CONFLICT (game_id, language_code) DO NOTHING;
