INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoggy 2', 'Hoggy 2 is the long awaited sequel to the 2010 mobile hit, Hoggy! Take control of Hoggy and Hogatha, two painfully adorable slime-molds, on a quest to rescue their children from the Moon Men! Slime molds are sticky... so whenever you jump, you stick to the ceiling! Use this gravity-swapping ability to conquer over two hundred unique levels as you seek enough keys to reach the moon! Get Hoggy 2 because you deserve a classic platformer with a twist!' FROM games WHERE igdb_id = 28916 ON CONFLICT (game_id, language_code) DO NOTHING;
