INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Through the Ages', 'This is the official adaptation of Vlaada Chvátil''s strategy classic. This is your chance to make history. You begin with a small tribe. As you expand your farms and mines, you lay the groundwork for technological advancements, better governments, and grand wonders. Your military might supports your political skill as you guide your civilization to greatness.' FROM games WHERE igdb_id = 87726 ON CONFLICT (game_id, language_code) DO NOTHING;
