INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Elder Scrolls: Legends', 'The Elder Scrolls: Legends is a strategy card game that explores the series'' characters, creatures, deities, and lore. Whether you have 10 minutes or five hours, Legends provides a variety of gameplay modes and challenges that are easy-to-learn but difficult to master. Built with all levels of players in mind, Legends offers accessible gameplay for beginners who want to get started quickly, and the game''s depth keeps expert players engaged. With a wide variety of deck types and strategies, no two games are ever the same.' FROM games WHERE igdb_id = 11120 ON CONFLICT (game_id, language_code) DO NOTHING;
