INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Birthdays the Beginning', '"From the legendary creator, Mr. Yasuhiro Wada (TOYBOX Inc.), comes Birthdays the Beginning: a new sandbox game in which players create cube-shaped worlds that give rise to diverse and unique lifeforms. With careful experimentation, players can shape the geography and alter the temperature of each world to create the conditions for life and witness the birth of an entire ecosystem!"' FROM games WHERE igdb_id = 26611 ON CONFLICT (game_id, language_code) DO NOTHING;
