INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mars Simulator: Red Planet', 'Mars – the future of mankind. Experience “Phase 1 – Exploration”, blast off on a journey into the unknown and solve the mystery of Mars. Land your rover on the red rocks of the fourth planet. Collect rock samples and drill for more. Photograph the landscape and transmit the data back to Earth.' FROM games WHERE igdb_id = 29591 ON CONFLICT (game_id, language_code) DO NOTHING;
