INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nonogram Galaxy', 'The goal is to find out which of the squares should be painted (or left blank), to form a figure, which will emerge when the hobby is solved correctly. Each number, on top of each column and to the left of each row, indicates how many squares must be filled in the grid, forming blocks. There must be at least one blank space between one block and another. After completing the grid, the image will be revealed.' FROM games WHERE igdb_id = 145799 ON CONFLICT (game_id, language_code) DO NOTHING;
