INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa''s Hot Doggeria HD', 'SPapa''s Hot Doggeria HD is a cooking simulation game where players manage a hot dog restaurant. Customers order specific hot dog combinations, and players must carefully prepare and assemble orders by grilling sausages, selecting toppings, and serving meals within a time limit. The game features increasingly complex customer requests and requires players to balance speed and accuracy. As part of the "Papa''s" series of restaurant management games, it offers progressive difficulty levels and challenges players to improve their food preparation and customer service skills.' FROM games WHERE igdb_id = 88892 ON CONFLICT (game_id, language_code) DO NOTHING;
