INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Awaits: 10H', 'Awaits;10H is an English Yume Nikki fangame created for the 2017 Dream Diary Jam. It is a prequel to the game Hikensha. It follows the story of a young boy named Yarishi, who is having a hard time with many familiar problems, but that''s about to change, as unknown forces lurk around the house and his dreams watching him constantly. Your goal is to collect effects as well as eight seeds that are scattered throughout the dream world.' FROM games WHERE igdb_id = 201620 ON CONFLICT (game_id, language_code) DO NOTHING;
