INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Girl in the City', 'With her journalism degree in her pocket, Laura leaves her small-town home to take a bite out of the Big Apple. She dreams of becoming a freelance journalist with a major New York women''s magazine, but the road is long and fraught with pitfalls. Seek out information on the busy life of New Yorkers in order to write good articles, meet new people and become the most prominent columnist.' FROM games WHERE igdb_id = 139722 ON CONFLICT (game_id, language_code) DO NOTHING;
