INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demons Age', '“Demons Age” is a classical Role-playing game, designed to be a modern successor of grate classic videogames such as “Baldur''s gate” and “The Temple of Elemental Evil”.  Despite “Demons Age” being highly inspired in D&D projects such ToEE, Chaos Chronicles or Baldur’s Gate, follows its own perspective on a whole new fictional world. Bigmoon took the artistic freedom to innovate, create new fictional locations, interesting characters, a captivating plot, and a whole new world to discover, experience, and gameplay.' FROM games WHERE igdb_id = 55050 ON CONFLICT (game_id, language_code) DO NOTHING;
