INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Azriel', 'The least boring brain trainer in the world. Most brain training programs are dull mini-games where the player quickly loses interest in playing. Project Azriel has been proven to increase fluid intelligence and it’s fun to play. Take down some zombies while training your brain to work better.' FROM games WHERE igdb_id = 74193 ON CONFLICT (game_id, language_code) DO NOTHING;
