INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Fighter', 'Deus Apparatus, an evil machine, has set fires to five regions. In this action packed game, it is your job as a fire fighter to extinguish all the fires. Put out fires before they destroy buildings and trees. These fires spread rapidly, but you can use your ax, water, and shovel to gain control of the fires. Fire Fighter as 50 levels.' FROM games WHERE igdb_id = 208503 ON CONFLICT (game_id, language_code) DO NOTHING;
