INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Town: Haunted House', 'It’s a regular house when the lights are on, but when you switch them off it becomes a Haunted house packed with new characters to play with, rooms to discover and adventures to explore.  Plunge in to a bath with a friendly skeleton. We dare you to sleep in the masters bed room and discover the secret passage to the attic where our friendly witch is hiding.' FROM games WHERE igdb_id = 88967 ON CONFLICT (game_id, language_code) DO NOTHING;
