INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarHorse Pocket', 'StarHorse Pocket is a smartphone horse racing simulation game featuring horse breeding, training, and competitive racing. Players can breed horses using champion lineages, compete with virtual horses and jockeys, and earn virtual medals and prizes. The game includes realistic race conditions, multiple camera views, and voice-acted secretary characters to assist in training and management. Players can participate in weekend race events and high-level competitions like WBC and SWBC. The game uses Live2D character models and provides a detailed racing experience. It is strictly for entertainment, with no real-money gambling involved, and is designed for players interested in horse racing strategy and management.' FROM games WHERE igdb_id = 108764 ON CONFLICT (game_id, language_code) DO NOTHING;
