INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worshippers', 'It''s hard to be a god! Worshipper is a fast-paced strategy combined with collectible card game. Explore and conquer the land, face dreadful creatures, lead your people to glory! With every victory you will unlock new units, spells and buildings, use them to develop your own unique strategies!' FROM games WHERE igdb_id = 74926 ON CONFLICT (game_id, language_code) DO NOTHING;
