INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Army: Fast Fingers Shmup', 'Tank Army: Fast Fingers Shmup is a fast-paced action-packed shoot ''em up game. Assembling a line of tanks, the game is played by tapping on a tank in order to fire at the enemy as you move around the terrain. You can use various bonuses in the form of air strikes and other useful support units and items. Enjoy the exciting one minute stages that you can pick up and play everywhere.' FROM games WHERE igdb_id = 175366 ON CONFLICT (game_id, language_code) DO NOTHING;
