INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krabat: The Secret of the Sorbian King', '"Krabat" is a classic point-and-click adventure game about the famous Sorbian fairy-tale figure Krabat. Adventure scenes drawn by hand which take you to historic events and places such as Moritzburg Castle near Dresden, or to Bautzen. Authentic Sorbian voice recordings and optional subtitles in English, German, Lower and Upper Sorbian.' FROM games WHERE igdb_id = 186722 ON CONFLICT (game_id, language_code) DO NOTHING;
