INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Box', 'Fighting Box is a casual game with characters that use boxing gloves, the player must to hit the opponent until his energy bar drain out, or the opponent fall out from the ring. The game use procedural levels, so the player can play as long as he survives or until the time out per round. This is one more game made on Blender Game Engine, i hope the players enjoy.' FROM games WHERE igdb_id = 68657 ON CONFLICT (game_id, language_code) DO NOTHING;
