INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashes Cricket', 'Ashes Cricket is the officially licensed video game of cricket’s greatest rivalry. Bringing all the fast paced action, big hits and skill that you see in the greatest cricket competition on earth, in both a more realistic and authentic way than ever before, you’ll be able to bathe your team in glory in the men’s and women’s 2017/2018 Ashes tours.' FROM games WHERE igdb_id = 68282 ON CONFLICT (game_id, language_code) DO NOTHING;
