INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Major League Gladiators', 'Major League Gladiators is a 2-player co-op shooter for VR. Each taking control of one of two classes, players will have to survive endless rounds of enemies by combining their unique movement and combat abilities as well as maintining each others resources.' FROM games WHERE igdb_id = 75817 ON CONFLICT (game_id, language_code) DO NOTHING;
