INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ARise', 'ARise is a puzzle game where players assist a small hero in navigating a dangerous environment. The game utilizes augmented reality, allowing players to summon the hazardous environment into their real-world space and view it through their device''s "lens." By exploring the levels within a familiar environment, players can leverage the power of perspective as their primary tool. By physically moving around and observing the environment from different angles, players can solve puzzles and advance the storyline of ARise''s hero.' FROM games WHERE igdb_id = 95777 ON CONFLICT (game_id, language_code) DO NOTHING;
