INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boom-Bahh', 'Solving puzzles is easy, solving logical puzzles is the last thing. Solving physical puzzles with elements of logic, backed up by explosions - is what you need, in order to test your smartness, agility and logical thinking.' FROM games WHERE igdb_id = 43537 ON CONFLICT (game_id, language_code) DO NOTHING;
