INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Sports', 'Experience ping-pong and tennis with realism only possible on the Vive. Play with friends, jump into a quick game online, or tackle career mode versus a spectrum of opponents in far ranging venues. Challenge your skills with realistic physics, or play in Fun Mode to get a boost in accuracy while you learn. Virtual Sports is the definitive sports game for virtual reality.' FROM games WHERE igdb_id = 29569 ON CONFLICT (game_id, language_code) DO NOTHING;
