INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fowlst', 'Fowlst is an action game about an owl who is trapped in Hell. Make your way through chamber after spooky chamber, smashing Demons and grabbing loot. Dodge bullets, battle huge bosses and try not to get chopped In half by a buzz saw. Trade your loot for sick powers like egg bombs and rockets so you can really show those demons who’s boss!' FROM games WHERE igdb_id = 36702 ON CONFLICT (game_id, language_code) DO NOTHING;
