INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Solitaire VR', 'Power Solitaire VR is a groundbreaking version of the Klondike solitaire card game that introduces unique game play only possible in Virtual Reality. Play alone, against an intelligent robot, or live multiplayer with others online. It''s a social VR game the whole family already knows how to play.' FROM games WHERE igdb_id = 29658 ON CONFLICT (game_id, language_code) DO NOTHING;
