INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scorch', 'Human age of industry caused a steady depletion of the ozone layer, that could not be stopped. Multiple holes in ozone opened up around the world, exposing Earth to the direct solar radiation. This affected plant growth and produced radicals in seawater that killed most marine organisms, and wildlife. Scorching the face of the Earth, turning it into a barren wasteland.' FROM games WHERE igdb_id = 30137 ON CONFLICT (game_id, language_code) DO NOTHING;
