INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Awe of Despair', 'Awe of Despair is a survival horror game which puts you in the shoes of a man who decides to ignore the stigma of the number 13. The goal of this game is to provide the player with a deeply immersive horror experience. You will run into disturbing creatures, discover new weapons, and solve puzzles as you battle your way out of this parallel world.' FROM games WHERE igdb_id = 75811 ON CONFLICT (game_id, language_code) DO NOTHING;
