INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thanksgivingistry', 'Manipulate a cube of cubes in 3 dimensions and find identical cubes to make them disappear! Thanksgivingistry adds a new holiday "spin" to the old classic of matching puzzle games. Whether you play by yourself or with your friends, Thanksgivingistry is guaranteed to deliver hours of relaxing holiday fun!' FROM games WHERE igdb_id = 55656 ON CONFLICT (game_id, language_code) DO NOTHING;
