INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reverse Dream', 'Reverse Dream is a Japanese Yume Nikki fangame. The main goal of the game is to explore Guratsuki''s dream worlds and collect effects (called Images (イメージ) in this game). Interestingly, each effect is based on a certain way of dying, with each effect having 死 (lit. Death) in its name.' FROM games WHERE igdb_id = 202327 ON CONFLICT (game_id, language_code) DO NOTHING;
